#!/usr/bin/env bash
# Owner order 2026-11-15: "adversarially debate all 3 sets of defaults; if they pass, proceed with them; if not, refactor and then proceed".
# Three sequential sessions (one slot free: the owner's other session is running), each one /sc:adversarial debate of one default set.
# Sonnet orchestrates; advocates are sonnet and haiku only (Opus is reserved for blind scoring). Results under results/debate/<n>-<name>/.
set -u -o pipefail
REPO=/home/coder/workspaces/worktrees/IronClaude/eval-tasklist-review-panel
SW=$REPO/.dev/eval-workspaces/tasklist-review-panel/20261114-sweep-sheet
MR=$REPO/.dev/brainstorms/20261113-223124-panel-process-redesign/merged-requirements.md
COMMON="Context: $SW/DESIGN.md (section 15.1 lists the owner decisions; sections 8, 9, 14 explain arms, briefs and gates), $SW/results/owner-decisions.md, and the brainstorm $MR (section 3.1(d) coverage matrix, section 5 experiment and gates D1-D7). The experiment compares a Sweep Sheet arm (SS) with the plain panel (Z0) and a plain-words arm (K) on hold-out plans, judged blind. Rules for this debate: run /sc:adversarial with advocates on claude-sonnet-5-5 and claude-haiku-5-5 ONLY (never Opus; Opus is reserved for blind scoring), at most 3 advocates, debate depth standard, output under the folder named below. Do not open any ground-truth*.json or score file. Do not stage, commit or push. Do not edit src/, tests/, .claude/, .dev/tasks/ or the brainstorm. Verdict rule: PASS means no blocking defect survived the debate (a blocking defect = the default would make the experiment unfair, unmeasurable or misleading, or would break a stated requirement); FAIL means at least one did. Write VERDICT.md in the output folder with: the verdict (PASS or FAIL), the surviving blocking defects with evidence, the non-blocking notes, and, on FAIL, the refactored value. On FAIL you must also apply the refactor, only to the files named below, then run: uv run --frozen --project $REPO pytest -p no:cacheprovider $SW/tests -q -m 'not freeze' and put the exit status and last line in VERDICT.md. If a test pins the old text, update the test together with the text and say so. A PASS changes no file."
run_one() { # n name task files
  local n=$1 name=$2 task=$3 files=$4 out=$SW/results/debate/$1-$2
  mkdir -p "$out"
  local P="$task $COMMON Output folder: $out. Files you may edit on FAIL: $files."
  local S=$(date +%s)
  ( cd "$REPO" && timeout 3600 claude -p --model claude-sonnet-5-5 --output-format json --no-session-persistence --permission-mode bypassPermissions <<<"$P" ) >"$out/session.json" 2>"$out/session.err"
  local RC=$?
  jq -r '[.[]|select(.type=="result")|.result]|.[0] // ""' "$out/session.json" > "$out/session-reply.md" 2>/dev/null
  echo "END debate $n-$name rc=$RC wall=$(( $(date +%s)-S ))s verdict=$(grep -m1 -oiE 'verdict[^A-Za-z]*(PASS|FAIL)' "$out/VERDICT.md" 2>/dev/null | head -1) $(date -u +%T)"
}
run_one 1 act-bands "Debate adversarially the owner decision 'per-class act-rate bands to pre-register' (DESIGN.md 15.1 row 2). The default is: C1 0.10-0.40, C2 0.20-0.45, C3 0.03-0.15, C4 0.50-0.75, C5 0.35-0.60, C6 0.05-0.30, C7 0.15-0.35, C8 0.40-0.65 (act = the share of runs in which a reviewer marks the planted item PROBLEM). Attack: are the bands derived from unmeasured estimates, are they wide enough to be unfalsifiable or too narrow to be fair, what happens when a class lands outside its band (what does the pre-registered rule do), does a band outside-result invalidate the arm unfairly, are bands needed per class when hold-out has few items per class, and is there a better pre-registration (for example one pooled band, or bands on the measured Z0 rate)." "$SW/DESIGN.md (section 15.1 and wherever bands are referenced), $SW/results/owner-decisions.md"
run_one 2 cb2-verbatim "Debate adversarially the owner decision 'CB-2 reword' (DESIGN.md 15.1 row 3, DD-7). The default is to leave CB-2 verbatim in every arm, although it says 'including every ledger row you marked PROBLEM' and the Z0 and K arms have no ledger; the design measures the '## Ledger' headings that Z0 and K reviewers write. Attack: does the dangling clause bias Z0 and K (confuse, add a ledger, change finding counts), does verbatim keep the arms comparable, would a reworded CB-2 for all arms break REQ-05 (verbatim) and REQ-23 (empty sheet equals Z0 by hash), what is the measurable harm and how large, and is there a better option (for example a per-arm variant with a hash recorded)." "$SW/briefs/cb2.txt, $SW/DESIGN.md (DD-7 and 15.1), $SW/results/owner-decisions.md, and any test or config that pins cb2's hash"
run_one 3 k-lead "Debate adversarially the owner decision 'approve the K-arm lead-in' (DD-14). The draft text of $SW/briefs/k-lead.txt is the lead-in of the plain-words arm K: 'Eight kinds of defect to look for in your own review of the plan. Each one says what to look for. A plan may have none of them, one of them or several.' followed by the eight card definition fields. Arm K exists to show whether the checks in plain words give the same gain as the Sweep Sheet (gate D7: SS must beat K by at least 0.04). Attack: is K a fair, strong control or a strawman (too weak makes SS look good, too strong makes SS lose for the wrong reason), does the lead-in leak anything about the hold-out answers, does it differ in length or tone from the SS brief in a way that confounds, does 'a plan may have none' discourage findings, and is the generated paragraph (lead-in plus card definitions) equivalent in information to what SS gives." "$SW/briefs/k-lead.txt, $SW/DESIGN.md (DD-14 and 15.1), $SW/results/owner-decisions.md, and any test that pins the lead-in"
echo ALLDONE
